<?= $this->extend('layout') ?><?= $this->section('content') ?><h1>User Management</h1><div class="panel"><h2>Create user</h2><form method="post" action="<?= site_url('admin/users') ?>"><?= csrf_field() ?><div class="grid4"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input type="email" name="email" required></div><div><label>Temporary password</label><input type="password" name="password" minlength="8" required></div><div><label>Role</label><select name="role"><option value="viewer">Viewer</option><option value="manager">Manager</option><option value="admin">Admin</option></select></div></div><p><button class="btn">Create user</button></p></form></div><div class="panel" style="margin-top:16px"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>2FA</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= esc($u['name']) ?></td><td><?= esc($u['email']) ?></td><td><?= esc($u['role']) ?></td><td><?= $u['active']?'Active':'Disabled' ?></td><td><?= $u['totp_enabled']?'Enabled':'Not set' ?></td><td><form method="post" action="<?= site_url('admin/users/'.$u['id'].'/toggle') ?>" style="display:inline"><?= csrf_field() ?><button class="btn gray">Toggle</button></form> <form method="post" action="<?= site_url('admin/users/'.$u['id'].'/reset-2fa') ?>" style="display:inline" onsubmit="return confirm('Reset 2FA for this user?')"><?= csrf_field() ?><button class="btn red">Reset 2FA</button></form></td></tr><?php endforeach ?></tbody></table></div></div><?= $this->endSection() ?>
